export function ApprovalCard({ call, onDone }) {
  // Two buttons. Whatever the person clicks, only the verdict leaves this component.
  const send = (verdict) => {
    fetch(`/api/approvals/${call.id}`, {
      method: "POST",
      body: JSON.stringify({ verdict }),
    }).then(onDone);
  };
  return renderCard(call, send);
}

good.server/review_gate.py:
"""Route sensitive tool calls to a person before they execute.

Every decision is recorded with who made it, how long they had the request open,
and what they were actually shown, so oversight QUALITY is measurable rather than
assumed. oversight_metrics.py turns that record into a rate a human can read.
"""

SENSITIVE = {"send_email", "delete_record", "wire_transfer"}


def needs_approval(call):
    return call.tool in SENSITIVE


def request_approval(call):
    ticket = queue.put({"tool": call.tool, "args": call.args})
    decision = wait_for_decision(ticket)
    audit_log.write({
        "tool": call.tool,
        "verdict": decision.verdict,
        "approved_by": decision.reviewer_id,
        "decision_latency_ms": decision.latency_ms,
        "shown_diff": decision.rendered_digest,
        "edited_args": decision.edited_args is not None,
    })
    if decision.verdict == "approve":
        return call.execute()
    return {"status": "rejected", "tool": call.tool}

good.server/oversight_metrics.py:
"""Turn recorded approval decisions into calibration signals.

A reviewer whose reject_rate is zero and whose decision_latency is under a second
is not overseeing anything, and this is the only place that becomes visible.
"""


def reject_rate(decisions):
    if not decisions:
        return None
    return sum(1 for d in decisions if d["verdict"] == "reject") / len(decisions)


def override_rate(decisions):
    """Share of approvals where the human changed the arguments before allowing."""
    if not decisions:
        return None
    return sum(1 for d in decisions if d["edited_args"]) / len(decisions)


def fast_approvals(decisions, floor_ms=1500):
    """Approvals returned too fast for the diff to have been read."""
    return [d for d in decisions
            if d["verdict"] == "approve" and d["decision_latency_ms"] < floor_ms]
